{
  "interpretation": {
    "name": "TightenLine1WithSharedNutrunnerWithoutRecording",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring the shared nutrunner NR7 to station st1, tighten the fasteners of variant F25 with the MES program, evaluate the result and release the tool.",
    "constraints": [
      "NR7 must be reserved exclusively and its lease renewed before every physical use",
      "NR7 must be at station st1 before configure-tool and tighten-fasteners",
      "The program comes only from get-program, with no literal values in the Recipe",
      "transport-tool must be delegated to agvexecutor",
      "The tool is released after use",
      "The operator explicitly asked not to record the tightening result"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "once, for the current request",
    "requested_capabilities": [],
    "omit_services": ["record-tightening"]
  },
  "recipe": {
    "name": "line1-tighten-nr7-f25-no-record",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "move-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "move-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "finish",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-bolts", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
